// Data loading and small statistics helpers.
// The dashboard reads one file: dashboard/tracts.geojson, regenerated by
// scripts/export_dashboard_geojson.py from the project's feature table.

export async function loadTracts(url = "tracts.geojson") {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Failed to load ${url}: ${res.status}`);
  const geojson = await res.json();
  return geojson.features;
}

export function values(features, key) {
  const out = [];
  for (const f of features) {
    const v = f.properties[key];
    if (typeof v === "number" && Number.isFinite(v)) out.push(v);
  }
  return out;
}

export function coverage(features, key) {
  return values(features, key).length;
}

export function median(nums) {
  if (!nums.length) return null;
  const s = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

export function quantileBreaks(nums, classes = 7) {
  if (!nums.length) return [];
  const s = [...nums].sort((a, b) => a - b);
  const breaks = [];
  for (let i = 1; i < classes; i++) {
    const v = s[Math.floor((i / classes) * s.length)];
    if (breaks[breaks.length - 1] !== v) breaks.push(v);
  }
  return breaks;
}

export function countBy(features, key) {
  const counts = {};
  for (const f of features) {
    const v = f.properties[key];
    if (v != null) counts[v] = (counts[v] || 0) + 1;
  }
  return counts;
}
